import subprocess
import os
import random
import sys

def task_func(directory, file_list):
    if not file_list:
        return None

    filename = random.choice(file_list)
    path = os.path.join(directory, filename)

    if not os.path.isfile(path):
        return None

    try:
        if os.path.splitext(path)[1].lower() in {".py", ".pyw"}:
            proc = subprocess.Popen([sys.executable, path], cwd=directory)
        else:
            proc = subprocess.Popen([path], cwd=directory)

        return proc.poll()
    except Exception:
        return None
